// Writes supabase/setup.sql: every migration in order, then the demo seed.
// Paste that one file into the Supabase SQL editor to set up a fresh project.
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { migrationFiles, seedSql } from './db.js';

const out = join(dirname(fileURLToPath(import.meta.url)), '..', 'setup.sql');

const parts = [
  '-- StockSense: complete database setup for a NEW Supabase project.',
  '-- Generated by `npm run bundle` in supabase/tests. Do not edit by hand;',
  '-- change the files in supabase/migrations and supabase/seed.sql instead.',
  '',
  ...migrationFiles().map((f) => `-- ===== ${f.name} =====\n${f.sql}`),
  `-- ===== seed.sql (demo data; skips itself if products already exist) =====\n${seedSql()}`,
];

writeFileSync(out, parts.join('\n'));
console.log(`wrote ${out}`);
